    'Change the website theme by choosing another from the list.' => 'आप उपलब्ध थीम की सूची से एक अलग विकल्प चुनकर वेबसाइट की थीम बदल सकते हैं।',
    'Change your password in three easy steps.' => 'Change your password in three easy steps.',
