    'Changes are saved when you click Save Information.' => 'जानकारी सहेजें बटन पर क्लिक करने के बाद सभी परिवर्तन सहेजे और लागू किए जाएंगे।',
    'Changing the address here does not update it with the delivery partner.' => 'यह ऑर्डर पहले ही एक डिलीवरी पार्टनर को सौंपा जा चुका है। यहां पता बदलने से डिलीवरी पार्टनर के साथ पता स्वचालित रूप से अपडेट नहीं होता है',
    'Changing the default currency requires updating every other exchange rate.' => 'किसी भिन्न मुद्रा को अपना डिफ़ॉल्ट बनाने के लिए, आपको अपनी सूची में प्रत्येक अन्य मुद्रा के लिए विनिमय दर को अपडेट करना होगा।',
    'Changing the default currency updates all listed exchange rates.' => 'जब आप डिफ़ॉल्ट मुद्रा बदलते हैं तो सभी सूचीबद्ध विनिमय दरें स्वचालित रूप से अपडेट हो जाएंगी।',
    'Changing the default currency updates business settings automatically.' => 'यदि आप डिफ़ॉल्ट मुद्रा बदलते हैं तो यह व्यवसाय सेटिंग पृष्ठ पर स्वचालित रूप से अपडेट हो जाएगी',
    'Character' => 'Character',
