    'Chat history' => 'चैट इतिहास',
    'Chat with us on WhatsApp' => 'हमारे साथ व्हाट्सएप पर चैट करें',
    'Chat with vendor' => 'विक्रेता से बातचीत करें',
    'Chatting List' => 'चैटिंग सूची',
    'Chattings' => 'चैटिंग',
    'Check Latest Blogs' => 'नवीनतम ब्लॉग जाँचें',
    'Check Please' => 'कृपया जांचें',
    'Check dependencies before cleaning data; other sections may be affected.' => 'किसी भी डेटा को साफ करने से पहले, उसकी निर्भरता को सावधानीपूर्वक सत्यापित करें, क्योंकि इस जानकारी की संवेदनशील प्रकृति के कारण यह अन्य अनुभागों को प्रभावित कर सकता है।',
    'Check every product delivery charge is up to date.' => 'कृपया सुनिश्चित करें कि उत्पाद के सभी डिलीवरी शुल्क अद्यतित हैं',
    'Check how the data you delete interacts with other sections.' => 'पहचानें और समझें कि हटाया जाने वाला डेटा सिस्टम के भीतर अन्य अनुभागों या मॉड्यूल के साथ कैसे इंटरैक्ट करता है।',
    'Check in Accept the ReCAPTCHA Terms of Service' => 'रीकैप्चा सेवा की शर्तों को स्वीकार करें चेक इन करें',
