    'Check the delivery address and contact details before continuing.' => 'कृपया आगे बढ़ने से पहले डिलीवरी पता, प्राप्तकर्ता जानकारी, संपर्क विवरण और डिलीवरी जानकारी सत्यापित करें',
    'Check the links are correct, or buttons will redirect wrongly.' => 'कृपया सुनिश्चित करें कि दिए गए लिंक सही हैं अन्यथा बटन गलत दिशा में रीडायरेक्ट हो जाएंगे',
    'Check the payment and receiving account details before marking this order paid.' => 'कृपया इस ऑर्डर को भुगतान के रूप में चिह्नित करने से पहले ग्राहक के भुगतान विवरण और प्राप्तकर्ता खाते की जानकारी की सावधानीपूर्वक समीक्षा करें।',
    'Check the payment information is correct before confirming.' => 'कृपया पुष्टि करने से पहले भुगतान जानकारी की जांच और सत्यापन करें कि यह सही है या नहीं',
    'Check your email provider documentation if you cannot find these details.' => 'यदि आप निश्चित नहीं हैं कि ये विवरण कहां मिलेंगे, तो मार्गदर्शन के लिए ईमेल प्रदाता के दस्तावेज़ या सहायता संसाधनों की जाँच करें',
