    'Choose a payment method such as bank, mobile wallet or card.' => 'अपनी पसंदीदा भुगतान विधि चुनें जैसे बैंक, मोबाइल वॉलेट, डिजिटल कार्ड आदि',
    'Choose a shipping method for every shop to continue' => 'Choose a shipping method for every shop to continue',
    'Choose a social network, add its link and save.' => 'सेटअप सोशल मीडिया लिंक में आप सोशल मीडिया नाम का चयन कर सकते हैं और सोशल मीडिया लिंक जोड़ सकते हैं। सोशल मीडिया लिंक और नाम सहेजें।',
    'Choose a withdrawal method and set up its payment details.' => 'व्यवस्थापक को निकासी अनुरोध भेजने के लिए अपना भुगतान विवरण सेट करने के लिए एक निकासी विधि का चयन करें।',
    'Choose attributes' => 'गुण चुनें',
    'Choose custom sorting to arrange products, categories, brands and stores yourself.' => 'ग्राहक वेबसाइट पर उत्पादों, श्रेणियों, ब्रांडों और दुकानों के प्रदर्शन क्रम को अनुकूलित करने के लिए, कस्टम सॉर्टिंग सूची विकल्प का चयन करें और उन्हें अपनी पसंद के अनुसार व्यवस्थित करें।',
    'Choose customer to add fund' => 'Choose customer to add fund',
    'Choose delivery type' => 'डिलीवरी का प्रकार चुनें',
    'Choose first' => 'पहले चुनें',
