    'Choose the method used to complete this verification.' => 'इस सेटअप में, आप वह विधि चुन सकते हैं जिसका उपयोग वे इस सत्यापन को पूरा करने के लिए करेंगे।',
    'Choose the social login options offered to customers.' => 'चुनें कि आप अपने ग्राहकों को ऐप और वेबसाइट तक पहुंचने के लिए कौन से सामाजिक लॉगिन विकल्प प्रदान करना चाहते हैं।',
    'Choose updated file' => 'अद्यतन फ़ाइल चुनें',
