    'Click a stat card to filter the list by that status.' => 'उस स्थिति के आधार पर सूची को फ़िल्टर करने के लिए कुल, अनुवादित या अअनुवादित कार्ड पर क्लिक करें।',
    'Click add new method to open the setup panel, then provide:' => 'सेटअप पैनल खोलने के लिए नई विधि जोड़ें पर क्लिक करें, फिर प्रदान करें:',
    'Click edit on a method to update its name, availability or fields.' => 'सूची में एक विधि ढूंढें और इसके सेटअप पैनल को खोलने और इसके नाम, उपलब्धता या फ़ील्ड को अपडेट करने के लिए संपादन आइकन पर क्लिक करें।',
    'Click for details' => 'विवरण के लिए क्लिक करें',
    'Click on Credentials in the left-hand menu' => 'बाएँ हाथ के मेनू में क्रेडेंशियल्स पर क्लिक करें',
    'Click on continue' => 'जारी रखें पर क्लिक करें',
