    'Customers' => 'ग्राहक',
    'Customers can add funds to the wallet with an available payment method.' => 'विकल्प को सक्षम करने से ग्राहक उपलब्ध भुगतान पद्धति के माध्यम से वॉलेट में धनराशि जोड़ सकेंगे',
    'Customers can browse and search products by brand inside any shop.' => 'सक्षम होने पर ग्राहक ब्रांड देख सकते हैं और वे किसी भी दुकान के अंदर प्रत्येक ब्रांड के उत्पादों को ब्राउज़ और खोज सकते हैं।',
    'Customers can pay for orders from their wallet balance.' => 'जब वॉलेट सुविधा सक्षम हो जाती है, तो ग्राहक ऑर्डर के भुगतान के लिए अपने वॉलेट बैलेंस का उपयोग कर सकते हैं।',
    'Customers cannot add money to their wallet.' => 'यदि विकलांग ग्राहक अपने वॉलेट में पैसे नहीं जोड़ पाएंगे',
    'Customers choose from these, so add the relevant input fields.' => 'जिसे ग्राहक चुनेंगे और भुगतान विधि के लिए प्रासंगिक इनपुट फ़ील्ड जोड़ेंगे',
    'Customers earn loyalty points on each order.' => 'यदि सक्षम किया गया है तो लॉयल्टी पॉइंट विकल्प ग्राहकों को ऑर्डर प्लेस करते समय प्रत्येक ऑर्डर पर उपलब्ध होगा',
    'Customers earn rewards when someone registers with their referral code.' => 'सक्षम होने पर ग्राहक तब पुरस्कार अर्जित करेंगे जब कोई उनके रेफरल कोड का उपयोग करके पंजीकरण करेगा।',
    'Customers get a wallet for placing orders and receiving refunds.' => 'सक्षम होने पर ग्राहक अपने खाते में वॉलेट विकल्प रख सकते हैं और ऑर्डर देते समय और रिफंड प्राप्त करते समय इसका उपयोग कर सकते हैं',
    'Customers must reach this amount before they can check out.' => ' इसका मतलब है कि ग्राहकों को चेकआउट के लिए आगे बढ़ने से पहले इस निर्दिष्ट राशि तक पहुंचने के लिए पर्याप्त आइटम जोड़ने की आवश्यकता होगी।',
    'Customers must verify their email during sign-up.' => 'यदि ईमेल सत्यापन चालू है, तो सुरक्षित लॉगिन प्रक्रिया सुनिश्चित करने के लिए ग्राहकों को साइन-अप के दौरान अपना ईमेल सत्यापित करना होगा।',
    'Customers must verify their phone with an OTP to sign up.' => 'यदि फ़ोन नंबर सत्यापन चालू है, तो ग्राहकों को साइनअप प्रक्रिया को पूरा करने के लिए एक ओटीपी के साथ अपना फ़ोन नंबर सत्यापित करना होगा।',
    'Customers pay and instantly download pre-uploaded digital products.' => 'तैयार उत्पाद डिलीवरी के लिए, ग्राहक भुगतान कर सकते हैं और पहले से अपलोड किए गए डिजिटल उत्पादों को तुरंत डाउनलोड कर सकते हैं।',
    'Customers pay by wallet, card or internet banking before shipping.' => 'Customers pay by wallet, card or internet banking before shipping.',
    'Customers pay first, then admin uploads the digital products for download.' => 'रेडी आफ्टर सेल डिलीवरी के लिए, ग्राहक पहले भुगतान करते हैं फिर व्यवस्थापक डिजिटल उत्पाद अपलोड करता है जो ग्राहकों के लिए डाउनलोड के लिए उपलब्ध हो जाते हैं',
    'Customers pay first, then the vendor uploads the digital products for download.' => 'रेडी आफ्टर सेल डिलीवरी के लिए, ग्राहक पहले भुगतान करते हैं फिर विक्रेता डिजिटल उत्पाद अपलोड करता है जो ग्राहकों के लिए डाउनलोड के लिए उपलब्ध हो जाता है',
    'Customers pay online by wallet, card or internet banking at checkout.' => 'डिजिटल भुगतान ग्राहकों को मोबाइल वॉलेट जैसे (bkash, nagad, रॉकेट) क्रेडिट डेबिट कार्ड या ऑर्डर दिए जाने पर सिस्टम के भीतर एकीकृत इंटरनेट बैंकिंग जैसे तरीकों का उपयोग करके अपने ऑर्डर के लिए ऑनलाइन भुगतान करने की सुविधा देता है।',
    'Customers recover accounts with a code sent by email or phone.' => 'Customers recover accounts with a code sent by email or phone.',
    'Customers refer friends with a code and earn rewards.' => 'ग्राहकों को रेफरल कोड का उपयोग करके अपने व्यवसाय को मित्रों और परिवार को संदर्भित करने और पुरस्कार अर्जित करने की अनुमति दें।',
    'Customers sign in with Apple credentials, on Apple devices only.' => 'ऐप्पल लॉगिन सक्षम करने से ग्राहक केवल ऐप्पल डिवाइस के लिए अपने मौजूदा ऐप्पल लॉगिन क्रेडेंशियल का उपयोग करके साइट पर लॉग इन कर सकते हैं',
    'Customers sign in with a phone number and OTP, not a password.' => 'Customers sign in with a phone number and OTP, not a password.',
    'Customers sign in with a social media account.' => 'सामाजिक लॉगिन के साथ ग्राहक इस सुविधा को सक्षम करने के लिए सोशल मीडिया खातों का उपयोग करके लॉग इन कर सकते हैं',
    'Customers sign in with their existing Facebook credentials.' => 'फेसबुक लॉगिन सक्षम करने से ग्राहक अपने मौजूदा फेसबुक क्रेडेंशियल्स का उपयोग करके साइट पर लॉग इन कर सकते हैं',
    'Customers sign in with their existing Google credentials.' => 'Google लॉगिन सक्षम करने से ग्राहक अपने मौजूदा जीमेल क्रेडेंशियल का उपयोग करके साइट पर लॉग इन कर सकते हैं',
