    'Enable Google login and test it before going live.' => 'अपने एप्लिकेशन की सेटिंग में Google लॉगिन विकल्प सक्षम करें और इसे लाइव वातावरण में तैनात करने से पहले एकीकरण का पूरी तरह से परीक्षण करें',
    'Enable OpenAl Configuration' => 'OpenAl कॉन्फ़िगरेशन सक्षम करें',
    'Enable VAT/GST and choose whether tax is included or added.' => 'वैट/जीएसटी को सक्षम करने से लेकर यह चुनने तक कि वैट/टैक्स कीमतों में शामिल है या जोड़ा गया है, आपका पूरा नियंत्रण है।',
    'Enable an add-on and enter its purchase code to activate it.' => 'Enable an add-on and enter its purchase code to activate it.',
    'Enable and manage different variations of a product.' => 'किसी उत्पाद की विभिन्न विविधताओं को सक्षम और प्रबंधित करें।',
    'Enable customer chat over social media. WhatsApp is supported.' => 'यह अनुभाग आपको सोशल मीडिया के माध्यम से ग्राहक संचार सक्षम करने की अनुमति देता है। वर्तमान में, व्हाट्सएप चैट कार्यक्षमता समर्थित है।',
    'Enable digital payment to offer these options.' => 'इन भुगतान विकल्पों को उपलब्ध कराने के लिए, आपको डिजिटल भुगतान विकल्प को सक्षम करना होगा',
    'Enable its status to activate this page.' => 'इस पृष्ठ को कॉन्फ़िगर करने के लिए, इसे सक्रिय बनाने के लिए इसकी स्थिति को सक्षम करके शुरुआत करें।',
    'Enable mail configuration' => 'मेल कॉन्फ़िगरेशन सक्षम करें',
    'Enable offline payment to offer these options.' => 'इन भुगतान विकल्पों को उपलब्ध कराने के लिए, आपको ऑफ़लाइन भुगतान विकल्प को सक्षम करना होगा',
    'Enable preferred payment methods to make payments from customer app and website' => 'ग्राहक ऐप और वेबसाइट से भुगतान करने के लिए पसंदीदा भुगतान विधियों को सक्षम करें',
    'Enable the option to update the logo that appears on invoices' => 'चालान पर दिखाई देने वाले लोगो को अपडेट करने का विकल्प सक्षम करें',
    'Enable the status and set up the required information to activate.' => 'Enable the status and set up the required information to activate.',
    'Enable the status of the payment method.' => 'भुगतान विधि की स्थिति सक्षम करें.',
