    'Enable this option to make the marketing tool available for website utilization.' => 'वेबसाइट उपयोग के लिए मार्केटिंग टूल उपलब्ध कराने के लिए इस विकल्प को सक्षम करें।',
    'Enable this option to send email notifications.' => 'ईमेल सूचनाएं भेजने के लिए इस विकल्प को सक्षम करें।',
