    'Enable to apply this tax at checkout. Disabled taxes are ignored.' => 'इस कर को सक्षम या अक्षम करने के लिए स्थिति टॉगल का उपयोग करें। सक्षम होने पर, चेकआउट के दौरान कर स्वचालित रूप से लागू हो जाएगा। यदि इसे बंद कर दिया जाता है, तो यह कर किसी भी ऑर्डर गणना को प्रभावित नहीं करेगा।',
