    'Hides the page from vendors. Credentials they already saved are kept.' => 'वह पृष्ठ विक्रेता पैनल और विक्रेता ऐप से छिपा हुआ है, और पहले से सहेजे गए विक्रेताओं के क्रेडेंशियल हटाए जाने के बजाय रखे गए हैं।',
