    'How many images vendors can upload to the AI system.' => 'परिभाषित करें कि विक्रेताओं के लिए एआई सिस्टम का उपयोग करके कितनी छवियां अपलोड की जा सकती हैं।',
    'How many loyalty points equal one unit of currency.' => 'यह सेटिंग व्यवस्थापक को यह परिभाषित करने देती है कि 1 यूनिट मुद्रा के बराबर कितने लॉयल्टी पॉइंट हैं',
    'How many rows are shown in the list.' => 'यह संख्या इंगित करती है कि सूची या तालिका में कितना डेटा दिखाया जाएगा',
    'How many times AI can generate data for each vendor panel element.' => 'सेट करें कि एआई विक्रेता पैनल या ऐप के प्रत्येक तत्व के लिए कितनी बार डेटा उत्पन्न कर सकता है',
    'How many times AI can generate data from the customer panel.' => 'सेट करें कि AI कितनी बार ग्राहक पैनल या ऐप से डेटा उत्पन्न कर सकता है',
