    'How many times a user can enter the OTP.' => 'कोई उपयोगकर्ता कितनी बार ओटीपी दर्ज करने का प्रयास कर सकता है, इसके लिए सेटिंग्स प्रबंधित करें।',
    'How many times a user can try to log in.' => 'उपयोगकर्ता कितनी बार सिस्टम में लॉग इन करने का प्रयास कर सकता है, इसके लिए सेटिंग्स प्रबंधित करें।',
