    'If disabled customer wallet option will be hidden from their account' => 'यदि ग्राहक अक्षम है तो वॉलेट विकल्प उनके खाते से छिपा दिया जाएगा',
    'If disabled customers can only pay through the system supported payment methods' => 'यदि विकलांग ग्राहक केवल सिस्टम समर्थित भुगतान विधियों के माध्यम से भुगतान कर सकते हैं',
    'If disabled customers will not receive notifications on their devices' => 'यदि अक्षम ग्राहकों को उनके डिवाइस पर सूचनाएं प्राप्त नहीं होंगी',
    'If disabled deliverymen do not need to verify the order deliveries' => 'यदि विकलांग डिलीवरीमैन को ऑर्डर डिलीवरी को सत्यापित करने की आवश्यकता नहीं है',
    'If disabled loyalty point option will be hidden from the customers account' => 'अक्षम होने पर लॉयल्टी पॉइंट विकल्प ग्राहक के खाते से छिपा दिया जाएगा',
    'If disabled the Business Identity information will be hidden from the invoice' => 'यदि अक्षम किया गया तो व्यवसाय पहचान की जानकारी चालान से छिपा दी जाएगी',
    'If disabled the Logo will be hidden from the invoice' => 'यदि अक्षम किया गया तो लोगो चालान से छिपा दिया जाएगा',
