    'Set 0 for unlimited. A higher number lets vendors use AI more.' => 'असीमित उपयोग की अनुमति देने के लिए 0 सेट करें  अधिक संख्या विक्रेताओं को AI का अधिक बार उपयोग करने देती है।',
    'Set Default Meta' => 'डिफ़ॉल्ट मेटा सेट करें',
