    'Set up at least one offline payment method to use offline payments.' => 'ऑफ़लाइन भुगतान का उपयोग करने के लिए, आपको कम से कम एक ऑफ़लाइन भुगतान विधि सेट करनी होगी',
    'Set up at least one payment method to use digital payments.' => 'डिजिटल भुगतान का उपयोग करने के लिए, आपको कम से कम एक भुगतान विधि स्थापित करनी होगी',
    'Set up email configuration here to enable sending emails via' => 'ईमेल भेजने को सक्षम करने के लिए यहां ईमेल कॉन्फ़िगरेशन सेट करें',
    'Set up facebook configuration first' => 'सबसे पहले फेसबुक कॉन्फ़िगरेशन सेट करें',
