    'Set up the Facebook configuration first to enable Facebook login.' => 'ऐसा लगता है कि आपका फेसबुक लॉगिन कॉन्फ़िगरेशन अभी तक सेट नहीं हुआ है। फेसबुक लॉगिन विकल्प को सक्षम करने के लिए, कृपया पहले फेसबुक कॉन्फ़िगरेशन सेट करें।',
    'Set up the app download information.' => 'यहां आप ऐप डाउनलोड ऑप्शन से जुड़ी जरूरी जानकारी सेटअप कर सकते हैं',
    'Set up the login options for customer access to the system.' => 'सिस्टम तक ग्राहक की पहुंच के लिए लॉगिन विकल्प सेट करें।',
