    'Set up the push notification messages for vendors on this page.' => 'इस पृष्ठ पर विक्रेताओं के लिए पुश अधिसूचना संदेश सेट करें।',
    'Set up the shipping responsibility and associated charges for order delivery.' => 'ऑर्डर डिलीवरी के लिए शिपिंग जिम्मेदारी और संबंधित शुल्क निर्धारित करें।',
    'Set up the timeframe for the shipping method' => 'शिपिंग विधि के लिए समय सीमा निर्धारित करें',
