    'Sets the display order of products, categories, brands and stores.' => 'यह प्राथमिकता सेटअप सूची आपको चयनित मानदंडों के अनुसार उत्पादों, श्रेणियों, ब्रांडों और दुकानों के प्रदर्शन अनुक्रम को निर्धारित करने की अनुमति देती है।',
    'Sets this as the default withdraw method for vendors.' => 'यदि आप इस निकासी विधि को सक्षम करते हैं तो विक्रेता ऐप और विक्रेता पैनल में डिफ़ॉल्ट निकासी विधि के रूप में सेट किया जाएगा',
    'Setting' => 'सेटिंग',
