    'Show password' => 'Show password',
    'Show this card' => 'यह कार्ड दिखाओ',
    'Show vendors how your business works to attract them.' => 'यहां आप विक्रेताओं को दिखा सकते हैं कि आपका व्यवसाय उन्हें अपने सिस्टम में बिक्री के लिए आकर्षित करने के लिए कैसे काम कर रहा है',
    'Show your offer on the store details page.' => 'ग्राहक वेबसाइट और ऐप्स में स्टोर विवरण पृष्ठ पर अपना ऑफ़र दिखाएं',
    'Showing the brand tells customers who makes the item.' => 'आपके उत्पाद पृष्ठों पर ब्रांड नाम दिखाने से ग्राहकों को यह जानने में मदद मिलती है कि आइटम कौन बनाता है।',
    'Shown above the footer. One banner only. Max 2 MB, ratio 4:1.' => 'यह बैनर फ़ुटर अनुभाग से पहले होम पेज के नीचे दिखाई देता है, जब कोई फ़ुटर अनुभाग ब्राउज़ करता है तो ध्यान आकर्षित करता है और ऑफ़र या प्रचार प्रदर्शित करता है। आप केवल एक बैनर जोड़ सकते हैं. अपलोड करते समय, सुनिश्चित करें कि फ़ाइल का आकार 2 एमबी से कम है और छवि अनुपात 4:1 है।',
    'Shown as a separate line on bills, invoices and order summaries.' => 'वैट/टैक्स बिल, चालान और ऑर्डर सारांश पर एक अलग लाइन आइटम के रूप में दिखाई देता है।',
    'Shown as the sender on the shipping label.' => 'शिपिंग लेबल पर प्रेषक के रूप में दिखाया गया है।',
    'Shown at the top of your site or app.' => 'Shown at the top of your site or app.',
    'Shown below the main banner, up to two banners.' => 'Shown below the main banner, up to two banners.',
    'Shown beside the intro section, one at a time.' => 'Shown beside the intro section, one at a time.',
    'Shown in the header nav bar. Max 2 MB, ratio 4:1.' => 'यह बैनर लघु और प्रभावी ऑफ़र प्रदर्शित करने के लिए हेडर नेव बार अनुभाग पर दिखाई देता है। अपलोड करते समय, सुनिश्चित करें कि फ़ाइल का आकार 2 एमबी से कम है और छवि अनुपात 4:1 है।',
    'Shown on site entry. One banner only. Max 2 MB, ratio 1:1.' => 'जब उपयोगकर्ता वेबसाइट पर जाता है तो पॉपअप बैनर दिखाई देता है। यह एक विशिष्ट एकल प्रकार का बैनर है। आप एक समय में केवल एक बैनर सक्रिय कर सकते हैं। अपलोड करते समय, सुनिश्चित करें कि फ़ाइल का आकार 2 एमबी से कम है और छवि अनुपात 1:1 है।',
    'Shown to the driver at pickup.' => 'पिकअप पर ड्राइवर को दिखाया गया।',
    'Shows AI features in admin, vendor panel and app.' => 'इसे सक्षम करने से एडमिन, वेंडर पैनल और वेंडर ऐप में AI सुविधाएं सक्रिय हो जाएंगी',
    'Shows Customer Wallet as a refund method on the Admin Refund page.' => 'यदि सक्षम किया गया है, तो ऑर्डर रिफंड संसाधित करते समय ग्राहक वॉलेट भुगतान विधि एडमिन रिफंड पृष्ठ पर दिखाई देगी।',
    'Shows POS in the vendor panel and app.' => 'सक्षम होने पर पीओएस विकल्प विक्रेता पैनल और विक्रेता ऐप पर उपलब्ध होगा',
    'Shows customers what their points are worth in wallet money.' => 'यह ग्राहकों को उनके पॉइंट के मूल्य को समझने में मदद करता है जब वे उन्हें वॉलेट मनी में बदलना चाहते हैं।',
    'Shows each method required fields, who it applies to, and its status.' => 'प्रत्येक विधि के लिए आप इसके आवश्यक फ़ील्ड, यह किस पर लागू होता है, इसकी डिफ़ॉल्ट और सक्रिय स्थिति देख सकते हैं।',
    'Shows how data is organised across the database.' => 'यह अनुभाग दिखाता है कि डेटाबेस के विभिन्न भागों में डेटा कैसे व्यवस्थित किया जाता है।',
    'Shows if the request is' => 'दिखाता है कि अनुरोध है या नहीं',
    'Shows store availability, creation date and other details.' => 'यह दुकान विवरण अनुभाग आपके स्टोर के बारे में मुख्य जानकारी प्रदर्शित करता है, जैसे उनकी वर्तमान उपलब्धता, उनके निर्माण की तारीख और अन्य प्रासंगिक विवरण।',
    'Shows the AI shopping assistant icon on the storefront.' => 'Shows the AI shopping assistant icon on the storefront.',
    'Shows the AI shopping assistant icon to customers.' => 'Shows the AI shopping assistant icon to customers.',
    'Shows the App Store button in the website footer.' => 'सक्षम होने पर हर कोई वेबसाइट फ़ुटर में ऐप स्टोर बटन देख सकता है',
    'Shows the App Store download button in the footer.' => 'यदि सक्षम किया गया है तो ऐप स्टोर से डाउनलोड बटन फ़ुटर अनुभाग में दिखाई देगा',
    'Shows the Google Play button in the website footer.' => 'सक्षम होने पर हर कोई वेबसाइट फ़ुटर में Google Play Store बटन देख सकता है',
    'Shows the blog section on the website.' => 'इस विकल्प को सक्षम करने से ब्लॉग अनुभाग दर्शकों के लिए वेबसाइट पर दृश्यमान हो जाएगा',
    'Shows the payment account details and what the customer must provide.' => 'प्रत्येक विधि के लिए, आपको भुगतान खाते की जानकारी और ग्राहक को भुगतान के दौरान क्या प्रदान करना होगा, इसका विवरण मिलेगा।',
    'Shows the product in the clearance section on the app and website.' => 'ग्राहक ऐप और वेबसाइट में क्लीयरेंस ऑफर अनुभाग में उत्पाद शो जोड़ें',
    'Shows the translated values for the selected language against the default.' => 'इस पृष्ठ पर, आप वर्तमान डिफ़ॉल्ट भाषा के आधार पर चयनित भाषा के लिए अनुवादित मान देख सकते हैं।',
    'Shows this FAQ in the app and website.' => 'यदि आप सक्षम करते हैं तो यह FAQ उपयोगकर्ता ऐप और वेबसाइट में दिखाया जाएगा',
    'Shows this banner on the website and app.' => 'सक्षम होने पर यह बैनर वेबसाइट और ग्राहक ऐप पर उपलब्ध होगा',
    'Shows this brand on the website and app.' => 'सक्षम होने पर यह ब्रांड वेबसाइट और ग्राहक ऐप पर उपलब्ध होगा',
    'Shows this category in the homepage category section.' => 'यदि इस श्रेणी को सक्षम किया गया है तो यह वेबसाइट में श्रेणीवार उत्पाद अनुभाग और होमपेज पर ग्राहक ऐप से दिखाई देगी',
    'Shows this category on the home page.' => 'इस श्रेणी को होम श्रेणी के रूप में दिखाने के लिए चालू करें, या इसे छिपाने के लिए बंद करें।',
    'Shows this clearance product on the website and app.' => 'सक्षम होने पर यह क्लीयरेंस बिक्री उत्पाद वेबसाइट और ऐप पर उपयोगकर्ताओं के लिए उपलब्ध होगा',
    'Shows this coupon on the website and app.' => 'सक्षम होने पर यह कूपन वेबसाइट और ग्राहक ऐप पर उपलब्ध होगा',
    'Shows this deal of the day on the website and app.' => 'सक्षम होने पर दिन का यह सौदा वेबसाइट और ग्राहक ऐप पर उपलब्ध होगा',
    'Shows this featured deal on the website and app.' => 'सक्षम होने पर यह विशेष डील वेबसाइट और ग्राहक ऐप पर उपलब्ध होगी',
    'Shows this flash sale on the website and app.' => 'सक्षम होने पर यह फ्लैश सेल वेबसाइट और ग्राहक ऐप पर उपलब्ध होगी',
    'Shows this payment in the dropdown when a withdraw request is sent.' => 'यदि आप स्थिति चालू करते हैं, तो व्यवस्थापक को निकासी अनुरोध भेजे जाने पर यह भुगतान ड्रॉपडाउन सूची में दिखाई देगा।',
    'Shows this product on the website and app.' => 'सक्षम होने पर यह उत्पाद वेबसाइट और ग्राहक ऐप पर उपलब्ध होगा',
    'Shows this review on the website and app.' => 'सक्षम होने पर कोई भी इस समीक्षा को उपयोगकर्ता वेबसाइट और ग्राहक ऐप पर देख सकता है',
    'Shows this section on the vendor registration page.' => 'जब आप स्थिति चालू करेंगे तो यह अनुभाग विक्रेता पंजीकरण पृष्ठ में दिखाई देगा',
    'Shows this shipping method at checkout in the app and website.' => 'यदि आप सक्षम करते हैं तो यह शिपिंग विधि ग्राहक चेकआउट के लिए उपयोगकर्ता ऐप और वेबसाइट में दिखाई जाएगी',
    'Shows your current terms and conditions on completed invoices.' => 'इस सेटिंग के माध्यम से अपने ग्राहकों को वर्तमान नियमों और शर्तों को पूर्ण चालान पर दिखाकर सूचित रखें।',
    'Shows your current version and the latest available update.' => 'इस पेज में आपको यह जानकारी मिलेगी कि आप वर्तमान में सिस्टम का कौन सा संस्करण उपयोग कर रहे हैं और अपडेट के लिए नवीनतम संस्करण कौन सा उपलब्ध है।',
    'Sidebar Banner' => 'साइडबार बैनर',
