    'The bonus is deducted from the admin wallet as an expense.' => 'बोनस राशि एडमिन वॉलेट से काट ली जाएगी और एडमिन व्यय के रूप में मानी जाएगी',
    'The city TCS collects from, spelled the way TCS spells it.' => 'टीसीएस जिस शहर से आपके पार्सल एकत्र करता है, उसे टीसीएस जिस तरह से लिखता है, उसी तरह लिखा जाता है।',
