    'The customer pays cash when the order is delivered.' => 'कैश ऑन डिलीवरी (कॉड) का मतलब है कि ग्राहक अपने ऑनलाइन ऑर्डर के लिए नकद भुगतान करते हैं जब डिलीवरी व्यक्ति इसे उनके पते पर लाता है।',
    'The customer picks an offline method and fills in the required details.' => 'जब कोई ग्राहक चेकआउट के दौरान  ऑफ़लाइन भुगतान  चुनता है और अपनी पसंदीदा भुगतान विधि चुनता है, तो उन्हें भुगतान की पुष्टि करने के लिए सभी आवश्यक जानकारी भरनी होगी',
    'The customer verifies with the option you select.' => 'नीचे से आपके द्वारा चुने गए विकल्प को ग्राहक द्वारा ग्राहक ऐप/वेबसाइट से सत्यापित करना होगा',
    'The date they were created and other relevant details' => 'उनके निर्माण की तारीख और अन्य प्रासंगिक विवरण',
