    'The path' => 'पथ',
    'The path is required' => 'पथ आवश्यक है',
    'The payment info id is invalid' => 'भुगतान जानकारी आईडी अमान्य है',
    'The payment is processed electronically and transferred to your business account.' => 'भुगतान इलेक्ट्रॉनिक रूप से संसाधित किया जाता है और आपके व्यावसायिक खाते में स्थानांतरित कर दिया जाता है।',
    'The phone number may not be greater than 20 characters' => 'फ़ोन नंबर 20 अक्षरों से अधिक नहीं हो सकता',
