    'The platform name (e.g., facebook, instagram, twitter).' => 'प्लेटफ़ॉर्म का नाम (जैसे, फेसबुक, इंस्टाग्राम, ट्विटर)।',
    'The point-of-sale feature is active for vendors.' => 'विक्रेता के लिए सक्रिय स्थिति इंगित करती है कि बिक्री बिंदु सुविधा वर्तमान में विक्रेता के रूप में काम कर रही है।',
    'The previous partner is not canceled. Cancel to avoid a duplicate pickup.' => 'पिछला डिलीवरी पार्टनर स्वचालित रूप से रद्द नहीं किया जाता है, डुप्लिकेट पिकअप से बचने के लिए सीधे उनके साथ शिपमेंट रद्द करें',
    'The public folder makes files viewable by anyone online.' => 'सार्वजनिक फ़ोल्डर आपकी कुछ फ़ाइलों और फ़ोल्डरों को ऑनलाइन किसी के भी द्वारा देखने योग्य बनाता है, भले ही उनके पास कोई खाता न हो।',
    'The publish date is not a valid date' => 'प्रकाशन दिनांक मान्य दिनांक नहीं है',
    'The publishing date shown to customers.' => 'वह दिनांक चुनें जिसे आप ग्राहकों को ब्लॉग प्रकाशन दिनांक के रूप में दिखाना चाहते हैं',
    'The quantity cannot be updated because the product has been modified' => 'मात्रा अद्यतन नहीं की जा सकती क्योंकि उत्पाद संशोधित कर दिया गया है',
    'The reorder point is the minimum stock level for a product.' => 'पुन: ऑर्डर स्तर जिसे पुन: ऑर्डर बिंदु भी कहा जाता है, किसी उत्पाद के लिए न्यूनतम स्टॉक स्तर है।',
    'The request method is not allowed for this url' => 'इस यूआरएल के लिए अनुरोध विधि की अनुमति नहीं है',
    'The screen itself will be built in a later release' => 'The screen itself will be built in a later release',
    'The script id may only contain letters, numbers, dashes, dots and underscores' => 'स्क्रिप्ट आईडी में केवल अक्षर, संख्याएँ, डैश, बिंदु और अंडरस्कोर हो सकते हैं',
    'The second number from the same click. Lalamove sends the rider here.' => 'समान Google मानचित्र से दो संख्याओं में से दूसरे पर क्लिक करें। लालामूव सवार को ठीक इसी बिंदु पर भेजता है।',
    'The secondary color is like its helpful supporting actor.' => 'द्वितीयक रंग उसके सहायक सहायक अभिनेता की तरह है।',
    'The selected customer does not exist' => 'चयनित ग्राहक मौजूद नहीं है',
    'The selected delivery partner is not enabled' => 'चयनित डिलीवरी पार्टनर सक्षम नहीं है',
    'The service key ID, shown after AuthKey in the filename.' => 'यह सेवा कुंजी आईडी फ़ाइल है और AuthKey के बाद भी यह कुंजी आईडी है',
    'The smallest amount a customer can add to their wallet.' => 'वह न्यूनतम राशि जो कोई ग्राहक एक बार में अपने वॉलेट में जोड़ सकता है।',
    'The smallest amount a new bid must add to the highest bid.' => 'The smallest amount a new bid must add to the highest bid.',
    'The smallest cart total a customer must reach to check out.' => 'न्यूनतम ऑर्डर राशि आपको ग्राहकों की शॉपिंग कार्ट के लिए आवश्यक न्यूनतम कुल मूल्य निर्धारित करने देती है, इससे पहले कि वे अपनी खरीदारी पूरी कर सकें।',
    'The spinning animation shown while a page loads.' => 'लोडर वह छोटी घूमती हुई एनीमेशन या छवि है जो कभी-कभी वेब पेज लोड होने के दौरान देखी जाती है, जैसे उत्पादों को ब्राउज़ करते समय।',
    'The station your account is registered at in the country above.' => 'ऊपर चयनित ऑपरेटिंग देश में आपका खाता जिस स्टेशन पर पंजीकृत है।',
    'The system will not apply any VAT/Tax to these orders.' => 'सिस्टम इन आदेशों पर कोई वैट/टैक्स लागू नहीं करेगा।',
    'The title may not be greater than 255 characters' => 'शीर्षक 255 अक्षरों से अधिक नहीं हो सकता',
    'The two-in-one benefits of ‘Offline Payment Method’ Feature' => ' ऑफ़लाइन भुगतान पद्धति  सुविधा के टू-इन-वन लाभ',
    'The unique ID of the order' => 'ऑर्डर की अद्वितीय आईडी',
    'The uploaded file type is not supported' => 'The uploaded file type is not supported',
