    'The url is required' => 'यूआरएल आवश्यक है',
    'The vacation end date is required' => 'The vacation end date is required',
    'The vacation start date is required' => 'The vacation start date is required',
    'The vendor handles shipping for vendor-wise orders.' => 'जब आप विक्रेता के अनुसार शिपिंग विधि चुनते हैं तो विक्रेता शिपिंग ज़िम्मेदारियाँ संभालेंगे।',
    'The vendor ships directly to the customer for these orders.' => 'विक्रेता-वार शिपिंग का मतलब है कि जब किसी ऑर्डर के लिए इस शिपिंग विधि का चयन किया जाता है, तो उत्पाद बेचने वाला व्यक्तिगत विक्रेता ग्राहक को सीधे शिपिंग प्रक्रिया के सभी पहलुओं को संभालने के लिए जिम्मेदार होगा।',
    'The visual symbol customers recognise your brand by.' => 'लोगो भौतिक स्टोर के बाहर अद्वितीय चिन्ह की तरह होता है - यह दृश्य प्रतीक है जो लोगों को आपके ब्रांड को तुरंत पहचानने में मदद करता है।',
    'The winner has claimed your auction item' => 'विजेता ने आपकी नीलामी वस्तु पर दावा किया है',
    'The writer may not be greater than 255 characters' => 'लेखक 255 अक्षरों से अधिक का नहीं हो सकता',
    'Theme Setup' => 'थीम सेटअप',
