    'This count is the summation of' => 'यह गिनती का योग है',
    'This count is the summation of delivered orders' => 'यह गिनती वितरित ऑर्डरों का योग है',
    'This country code already exists!' => 'This country code already exists!',
    'This deal has expired and cannot be updated.' => 'यह डील समाप्त हो गई है और इसे अपडेट नहीं किया जा सकता.',
