    'Vendors can set a minimum order amount for their shop.' => 'विकल्प को चालू करके, विक्रेता अपने दुकान के उत्पाद के लिए न्यूनतम ऑर्डर राशि निर्धारित कर सकता है।',
    'Vendors can set a minimum order amount for their stores.' => 'सक्षम होने पर विक्रेता अपने स्टोर के लिए न्यूनतम ऑर्डर राशि स्वयं निर्धारित कर सकते हैं',
    'Vendors can sign up and start listing products.' => 'इच्छुक विक्रेता साइन अप कर सकते हैं और अपने उत्पादों को आपके प्लेटफ़ॉर्म पर सूचीबद्ध करना शुरू कर सकते हैं।',
    'Vendors cannot create or manage their own websites.' => 'Vendors cannot create or manage their own websites.',
