    'Vendors cannot set a minimum order amount for their shop.' => 'विकल्प को बंद करने से, विक्रेता अपने दुकान के उत्पाद के लिए न्यूनतम ऑर्डर राशि निर्धारित नहीं कर सकता है।',
    'Vendors cannot set a minimum order amount; the admin sets it.' => 'यदि अक्षम विक्रेता अपने स्टोर के लिए न्यूनतम ऑर्डर राशि निर्धारित नहीं कर सकते हैं और व्यवस्थापक इसे निर्धारित करेगा',
    'Vendors connect their own delivery partner accounts and credentials.' => 'Vendors connect their own delivery partner accounts and credentials.',
