    'Vendors need admin approval before an updated shipping cost applies.' => 'यदि सक्षम किया गया है, तो विक्रेताओं को उनकी अद्यतन शिपिंग लागत लागू करने से पहले व्यवस्थापक अनुमोदन प्राप्त करना होगा।',
