    'Vendors sorted by join date, rating or alphabetically.' => 'विक्रेता सूची नवीनतम जुड़ाव के आधार पर सभी विक्रेताओं को व्यवस्थित करती है जिन्हें ग्राहक की पसंद और वर्णमाला क्रम में भी उच्च रेटिंग दी जाती है',
